mapper.select:
SELECT
,

FROM TB_RESEARCH_APP
WHERE RESEARCH_NO = #{researchNo}

ORDER BY RESEARCH_APP_SEQ DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT ,
FROM TB_RESEARCH_APP WHERE 1 = 1
ORDER BY REGIST_DT DESC, RESEARCH_APP_SEQ DESC LIMIT #{limit} OFFSET #{offset}

SELECT ,
FROM TB_RESEARCH_APP WHERE LEFT(REGEXP_REPLACE(CAST(REGIST_DT AS CHAR), '[^0-9]', ''), 8) >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 2 YEAR), '%Y%m%d') AND ( COALESCE(REPLACE(REPLACE(REPLACE(APP_HPHONE, '-', ''), ' ', ''), '.', ''), '') != '' OR COALESCE(REPLACE(REPLACE(REPLACE(APP_TELE, '-', ''), ' ', ''), '.', ''), '') != '' ) AND NOT EXISTS ( SELECT 1 FROM TB_BLACKLIST_MST blacklist WHERE blacklist.BLACK_YN = 'Y' AND ( ( COALESCE(REPLACE(REPLACE(REPLACE(blacklist.BLACK_USER_CONTACT, '-', ''), ' ', ''), '.', ''), '') != '' AND COALESCE(REPLACE(REPLACE(REPLACE(TB_RESEARCH_APP.APP_HPHONE, '-', ''), ' ', ''), '.', ''), '') != '' AND REPLACE(REPLACE(REPLACE(blacklist.BLACK_USER_CONTACT, '-', ''), ' ', ''), '.', '') = REPLACE(REPLACE(REPLACE(TB_RESEARCH_APP.APP_HPHONE, '-', ''), ' ', ''), '.', '') ) OR ( COALESCE(REPLACE(REPLACE(REPLACE(blacklist.BLACK_USER_CONTACT, '-', ''), ' ', ''), '.', ''), '') != '' AND COALESCE(REPLACE(REPLACE(REPLACE(TB_RESEARCH_APP.APP_TELE, '-', ''), ' ', ''), '.', ''), '') != '' AND REPLACE(REPLACE(REPLACE(blacklist.BLACK_USER_CONTACT, '-', ''), ' ', ''), '.', '') = REPLACE(REPLACE(REPLACE(TB_RESEARCH_APP.APP_TELE, '-', ''), ' ', ''), '.', '') ) OR ( COALESCE(blacklist.BLACK_USER_NAME, '') != '' AND COALESCE(TB_RESEARCH_APP.APP_NAME, '') != '' AND COALESCE(REPLACE(REPLACE(blacklist.BLACK_USER_BIRTH, '-', ''), '.', ''), '') != '' AND COALESCE(REPLACE(REPLACE(TB_RESEARCH_APP.APP_BIRTH, '-', ''), '.', ''), '') != '' AND blacklist.BLACK_USER_NAME = TB_RESEARCH_APP.APP_NAME AND REPLACE(REPLACE(blacklist.BLACK_USER_BIRTH, '-', ''), '.', '') = REPLACE(REPLACE(TB_RESEARCH_APP.APP_BIRTH, '-', ''), '.', '') ) ) )
AND (
APP_SEX = #{appSexCode}
)
AND (
LEFT(REGEXP_REPLACE(COALESCE(APP_BIRTH, ''), '[^0-9]', ''), 4) = #{appBirthYear} OR
( CHAR_LENGTH(REGEXP_REPLACE(COALESCE(APP_BIRTH, ''), '[^0-9]', '')) = 6 AND LEFT(REGEXP_REPLACE(COALESCE(APP_BIRTH, ''), '[^0-9]', ''), 2) = #{appBirthYearSuffix} ) OR
APP_BIRTH LIKE CONCAT('%', #{appBirthTerm}, '%') OR
)
AND (
APP_JOB LIKE CONCAT('%', #{appJobTerm}, '%')
)
AND (
APP_COMPANY LIKE CONCAT('%', #{appCompanyTerm}, '%')
)
AND (
APP_ADDR LIKE CONCAT('%', #{appAddrTerm}, '%')
)
AND (
OR ADD_COMMENT LIKE CONCAT('%', #{addCommentTerm}, '%')
OR RESEARCH_APP_SEQ IN
#{researchAppSeq}
)
ORDER BY REGIST_DT DESC, RESEARCH_APP_SEQ DESC LIMIT #{limit} OFFSET #{offset}

SELECT
,

FROM TB_RESEARCH_APP
WHERE RESEARCH_NO = #{researchNo}
  AND LEFT(REGEXP_REPLACE(CAST(REGIST_DT AS CHAR), '[^0-9]', ''), 8) = #{registDate}
ORDER BY RESEARCH_APP_SEQ DESC

SELECT COUNT(*)
FROM TB_RESEARCH_APP
WHERE RESEARCH_NO = #{researchNo}

SELECT COUNT(*)
FROM TB_RESEARCH_APP
WHERE RESEARCH_NO = #{researchNo}

