UPDATE TB_RESEARCH_APP
SET
    PROVIDE_YN = #{provideYn},
    MODIFY_DT = DATE_FORMAT(NOW(), '%Y%m%d')
WHERE RESEARCH_NO = #{researchNo}
  AND RESEARCH_APP_SEQ = #{researchAppSeq}
